import type { AppConfig } from '@/lib/nuxt/types/app-config'
import icons from '@/lib/nuxt/theme/icons'

export default {
  ui: {
    colors: {
      primary: 'green',
      secondary: 'blue',
      success: 'green',
      info: 'blue',
      warning: 'yellow',
      error: 'red',
      neutral: 'slate',
    },
    icons,
    prefix: undefined,
    tv: { twMergeConfig: {} },
  },
} as AppConfig & { ui: Record<string, any> }

import { ref } from 'vue'
import appConfig from '@/lib/nuxt/app-config'

/** useAppConfig 替身：返回固定 app.config */
export function useAppConfig() {
  return appConfig
}

/** useRoute 替身：按 location.pathname 提供最小路由信息 */
export function useRoute() {
  return {
    path: typeof window !== 'undefined' ? window.location.pathname : '/',
    query: {},
    params: {},
    hash: '',
    fullPath: typeof window !== 'undefined' ? window.location.href : '/',
    matched: [],
  }
}

/** useState 替身：内存版共享状态 */
const stateMap = new Map<string, ReturnType<typeof ref>>()
export function useState<T>(key: string, init?: () => T) {
  if (!stateMap.has(key)) {
    stateMap.set(key, ref(init?.()))
  }
  return stateMap.get(key) as ReturnType<typeof ref<T>>
}

/** useCookie 替身：localStorage 持久化 */
export function useCookie<T>(name: string, _options?: Record<string, any>) {
  const stored = typeof window !== 'undefined' ? window.localStorage.getItem(name) : null
  const value = ref<T | null>(stored ? (JSON.parse(stored) as T) : null)
  const watch = (cb: () => void) => {
    cb()
    return () => {}
  }
  return Object.assign(value, { watch })
}

/** useColorMode 替身 */
export function useColorMode() {
  return { value: ref('light'), preference: 'system' }
}

/** noop 替身 */
export function useRuntimeHook() {}
export function useNuxtApp() {
  return { $config: {}, runWithContext: (fn: () => void) => fn() }
}
export function onNuxtReady(cb: () => void) {
  cb()
}
export function useHead() {}
export function clearError() {}

import { defu } from 'defu'
import type { Locale, Direction } from '../types/locale'
import type { DeepPartial } from '../types/utils'

interface DefineLocaleOptions<M> {
  name: string
  code: string
  dir?: Direction
  messages: M
}

/* @__NO_SIDE_EFFECTS__ */
export function defineLocale<M>(options: DefineLocaleOptions<M>): Locale<M> {
  return defu<DefineLocaleOptions<M>, [{ dir: Direction }]>(options, { dir: 'ltr' })
}

/* @__NO_SIDE_EFFECTS__ */
export function extendLocale<M>(locale: Locale<M>, options: Partial<DefineLocaleOptions<DeepPartial<M>>>): Locale<M> {
  return defu<Locale<M>, [DefineLocaleOptions<M>]>(options, locale)
}

/* eslint-disable regexp/no-useless-quantifier */
/* eslint-disable regexp/no-super-linear-backtracking */
import { ref, computed, toValue } from 'vue'
import type { MaybeRef } from 'vue'
import { useEventListener, useActiveElement, useDebounceFn, useTimeoutFn } from '@vueuse/core'
import { useKbd } from './useKbd'

type Handler = (e?: any) => void

export interface ShortcutConfig {
  handler: Handler
  usingInput?: string | boolean
}

export interface ShortcutsConfig {
  [key: string]: ShortcutConfig | Handler | false | null | undefined
}

export interface ShortcutsOptions {
  chainDelay?: number
  layoutIndependent?: boolean
}

interface Shortcut {
  handler: Handler
  enabled: boolean
  chained: boolean
  // KeyboardEvent attributes
  key: string
  ctrlKey: boolean
  metaKey: boolean
  shiftKey: boolean
  altKey: boolean
  // code?: string
  // keyCode?: number
}

const chainedShortcutRegex = /^[^-]+.*-.*[^-]+$/
const combinedShortcutRegex = /^[^_]+.*_.*[^_]+$/
// keyboard keys which can be combined with Shift modifier (in addition to alphabet keys)
const shiftableKeys = ['arrowleft', 'arrowright', 'arrowup', 'arrowdown', 'tab', 'escape', 'enter', 'backspace']

// Simple key to code conversion for layout independence
function convertKeyToCode(key: string): string {
  // Handle single letters
  if (/^[a-z]$/i.test(key)) {
    return `Key${key.toUpperCase()}`
  }
  // Handle digits
  if (/^\d$/.test(key)) {
    return `Digit${key}`
  }
  // Handle function keys
  if (/^f\d+$/i.test(key)) {
    return key.toUpperCase()
  }
  // Handle common special keys
  const specialKeys: Record<string, string> = {
    space: 'Space',
    enter: 'Enter',
    escape: 'Escape',
    tab: 'Tab',
    backspace: 'Backspace',
    delete: 'Delete',
    arrowup: 'ArrowUp',
    arrowdown: 'ArrowDown',
    arrowleft: 'ArrowLeft',
    arrowright: 'ArrowRight'
  }
  return specialKeys[key.toLowerCase()] || key
}

export function extractShortcuts(items: any[] | any[][], separator: '_' | '-' = '_') {
  const shortcuts: Record<string, Handler> = {}

  function traverse(items: any[]) {
    items.forEach((item) => {
      if (item.kbds?.length && (item.onSelect || item.onClick)) {
        const shortcutKey = item.kbds.join(separator)
        shortcuts[shortcutKey] = item.onSelect || item.onClick
      }
      if (item.children) {
        traverse(item.children.flat())
      }
      if (item.items) {
        traverse(item.items.flat())
      }
    })
  }

  traverse(items.flat())

  return shortcuts
}

export function defineShortcuts(config: MaybeRef<ShortcutsConfig>, options: ShortcutsOptions = {}) {
  const chainDelay = options.chainDelay ?? 800
  const chainedInputs = ref<string[]>([])
  const clearChainedInput = () => {
    chainedInputs.value.splice(0, chainedInputs.value.length)
  }
  const debouncedClearChainedInput = useDebounceFn(clearChainedInput, chainDelay)

  // A standalone shortcut that is also the first key of a chained shortcut (e.g. `f` and `f-h`)
  // is held back until the chain either completes or the delay elapses, so pressing `f` doesn't
  // fire the standalone and swallow the chain (#5654). Its `preventDefault` already ran on keydown.
  let pendingShortcut: { shortcut: Shortcut, event: KeyboardEvent } | undefined
  const cancelPendingShortcut = () => {
    pendingShortcut = undefined
    pendingTimer.stop()
  }
  const runPendingShortcut = () => {
    const pending = pendingShortcut
    cancelPendingShortcut()
    if (!pending) {
      return
    }

    // Re-resolve instead of trusting the held snapshot: `enabled` may have changed in the
    // meantime (e.g. focus moved into an input), and the pending shortcut is always unmodified.
    const shortcut = standardShortcuts.value.find(s => s.key === pending.shortcut.key && !s.metaKey && !s.ctrlKey && !s.altKey && !s.shiftKey)
    if (shortcut?.enabled) {
      shortcut.handler(pending.event)
    }
  }
  const pendingTimer = useTimeoutFn(() => {
    runPendingShortcut()
    clearChainedInput()
  }, chainDelay, { immediate: false })

  const { macOS } = useKbd()
  const activeElement = useActiveElement()
  const layoutIndependent = options.layoutIndependent ?? false

  // precompute shiftable codes if layoutIndependent
  const shiftableCodes = shiftableKeys.map(k => convertKeyToCode(k))

  const onKeyDown = (e: KeyboardEvent) => {
    // Input autocomplete triggers a keydown event
    if (!e.key) {
      return
    }

    const useCode = layoutIndependent || e.altKey
    const alphabetKey = useCode ? /^Key[A-Z]$/i.test(e.code) : /^[a-z]{1}$/i.test(e.key)
    const shiftableKey = useCode ? shiftableCodes.includes(e.code) : shiftableKeys.includes(e.key.toLowerCase())

    let chainedKey
    // push either code or key depending on layoutIndependent flag
    chainedInputs.value.push(layoutIndependent ? e.code : e.key)
    // try matching a chained shortcut
    if (chainedInputs.value.length >= 2) {
      chainedKey = chainedInputs.value.slice(-2).join('-')

      for (const shortcut of chainedShortcuts.value) {
        if (shortcut.key !== chainedKey) {
          continue
        }

        if (shortcut.enabled) {
          // The chain completed, so the held-back standalone from its first key must not fire.
          cancelPendingShortcut()

          e.preventDefault()
          shortcut.handler(e)
        } else {
          // A disabled chain must not swallow the held-back standalone.
          runPendingShortcut()
        }
        clearChainedInput()
        return
      }
    }

    // This key didn't complete a chain, so honor any standalone held back by the previous key.
    runPendingShortcut()

    // try matching a standard shortcut
    for (const shortcut of standardShortcuts.value) {
      if (layoutIndependent) {
        // compare by code
        if (e.code !== shortcut.key) {
          continue
        }
      } else if (shortcut.altKey && e.altKey) {
        // Alt/Option modifies e.key on macOS (e.g. Alt+K → "˚"), so compare via e.code
        if (e.code !== convertKeyToCode(shortcut.key)) {
          continue
        }
      } else {
        if (e.key.toLowerCase() !== shortcut.key) {
          continue
        }
      }

      if (e.metaKey !== shortcut.metaKey) {
        continue
      }
      if (e.ctrlKey !== shortcut.ctrlKey) {
        continue
      }
      if (e.altKey !== shortcut.altKey) {
        continue
      }
      // Shift modifier is checked for alphabet keys, shiftable keys, explicit shift shortcuts,
      // or when shift is pressed alongside meta/ctrl (where shift doesn't transform the key value).
      // Without meta/ctrl, shift changes the key itself (e.g. / -> ?) so the check is skipped.
      if ((alphabetKey || shiftableKey || shortcut.shiftKey || (e.shiftKey && (e.metaKey || e.ctrlKey))) && e.shiftKey !== shortcut.shiftKey) {
        continue
      }

      // If this key also starts a chained shortcut, hold it back until the chain can complete.
      const isUnmodified = !shortcut.metaKey && !shortcut.ctrlKey && !shortcut.altKey && !shortcut.shiftKey
      if (isUnmodified && chainPrefixes.value.has(shortcut.key)) {
        if (shortcut.enabled) {
          // Must run now: preventDefault is a no-op once the event finished dispatching.
          e.preventDefault()
        }
        pendingShortcut = { shortcut, event: e }
        pendingTimer.start()
        return
      }

      if (shortcut.enabled) {
        e.preventDefault()
        shortcut.handler(e)
      }
      clearChainedInput()
      return
    }

    debouncedClearChainedInput()
  }

  const usingInput = computed(() => {
    const tagName = activeElement.value?.tagName
    const contentEditable = activeElement.value?.contentEditable

    const usingInput = !!(tagName === 'INPUT' || tagName === 'TEXTAREA' || contentEditable === 'true' || contentEditable === 'plaintext-only')

    if (usingInput) {
      return ((activeElement.value as any)?.name as string) || true
    }

    return false
  })

  // Map config to full detailled shortcuts
  const shortcuts = computed<Shortcut[]>(() => {
    return Object.entries(toValue(config)).map(([key, shortcutConfig]) => {
      if (!shortcutConfig) {
        return null
      }

      // Parse key and modifiers
      let shortcut: Partial<Shortcut>

      if (key.includes('-') && key !== '-' && !key.includes('_') && !key.match(chainedShortcutRegex)?.length) {
        console.trace(`[Shortcut] Invalid key: "${key}"`)
      }

      if (key.includes('_') && key !== '_' && !key.match(combinedShortcutRegex)?.length) {
        console.trace(`[Shortcut] Invalid key: "${key}"`)
      }

      const chained = key.includes('-') && key !== '-' && !key.includes('_')
      if (chained) {
        // convert each part to code if layoutIndependent, otherwise keep raw key
        if (layoutIndependent) {
          const parts = key.split('-').map(p => convertKeyToCode(p))
          shortcut = {
            key: parts.join('-'),
            metaKey: false,
            ctrlKey: false,
            shiftKey: false,
            altKey: false
          }
        } else {
          shortcut = {
            key: key.toLowerCase(),
            metaKey: false,
            ctrlKey: false,
            shiftKey: false,
            altKey: false
          }
        }
      } else {
        const keySplit = key.toLowerCase().split('_').map(k => k)
        let baseKey = keySplit.filter(k => !['meta', 'command', 'ctrl', 'shift', 'alt', 'option'].includes(k)).join('_')
        if (layoutIndependent) {
          baseKey = convertKeyToCode(baseKey)
        }
        shortcut = {
          key: baseKey,
          metaKey: keySplit.includes('meta') || keySplit.includes('command'),
          ctrlKey: keySplit.includes('ctrl'),
          shiftKey: keySplit.includes('shift'),
          altKey: keySplit.includes('alt') || keySplit.includes('option')
        }
      }
      shortcut.chained = chained

      // Convert Meta to Ctrl for non-MacOS
      if (!macOS.value && shortcut.metaKey && !shortcut.ctrlKey) {
        shortcut.metaKey = false
        shortcut.ctrlKey = true
      }

      // Retrieve handler function
      if (typeof shortcutConfig === 'function') {
        shortcut.handler = shortcutConfig
      } else if (typeof shortcutConfig === 'object') {
        shortcut = { ...shortcut, handler: shortcutConfig.handler }
      }

      if (!shortcut.handler) {
        console.trace('[Shortcut] Invalid value')
        return null
      }

      let enabled = true
      if (!(shortcutConfig as ShortcutConfig).usingInput) {
        enabled = !usingInput.value
      } else if (typeof (shortcutConfig as ShortcutConfig).usingInput === 'string') {
        enabled = usingInput.value === (shortcutConfig as ShortcutConfig).usingInput
      }
      shortcut.enabled = enabled

      return shortcut
    }).filter(Boolean) as Shortcut[]
  })

  // Cached so each keydown doesn't re-filter (and re-allocate) the shortcuts list.
  const chainedShortcuts = computed(() => shortcuts.value.filter(s => s.chained))
  const standardShortcuts = computed(() => shortcuts.value.filter(s => !s.chained))
  // First key of every chained shortcut, used to hold back a matching standalone shortcut.
  const chainPrefixes = computed(() => new Set(chainedShortcuts.value.map(s => s.key.split('-')[0])))

  return useEventListener('keydown', onKeyDown)
}

import { inject, provide, computed } from 'vue'
import type { ComputedRef, InjectionKey } from 'vue'
import type { AvatarGroupProps } from '../../../components/kit/XAvatarGroup.vue'

export const avatarGroupInjectionKey: InjectionKey<ComputedRef<{ size: AvatarGroupProps['size'], color: AvatarGroupProps['color'] }>> = Symbol('nuxt-ui.avatar-group')

/**
 * Reads `size` and `color` from a wrapping `<XAvatarGroup>`.
 *
 * **Always pass the raw `_props`, never the `useComponentProps` proxy** — the
 * fallback `props.size ?? avatarGroup?.value.size` must keep the wrapping group
 * winning over `<UTheme :props>`. To still apply theme defaults on bare avatars,
 * fall back to the proxy at the `tv()` call site: `size: size.value ?? props.size`.
 */
export function useAvatarGroup(props: { size: AvatarGroupProps['size'], color: AvatarGroupProps['color'] }) {
  const avatarGroup = inject(avatarGroupInjectionKey, undefined)

  const size = computed(() => props.size ?? avatarGroup?.value.size)
  const color = computed(() => props.color ?? avatarGroup?.value.color)
  provide(avatarGroupInjectionKey, computed(() => ({ size: size.value, color: color.value })))

  return {
    size,
    color
  }
}

import { computed, toValue } from 'vue'
import type { MaybeRefOrGetter } from 'vue'
import { useAppConfig } from '@/lib/nuxt/imports'
import type { AvatarProps } from '../../../components/kit/XAvatar.vue'
import type { IconProps } from '../../../components/kit/XIcon.vue'

export interface UseComponentIconsProps {
  /**
   * Display an icon based on the `leading` and `trailing` props.
   * @IconifyIcon
   */
  icon?: IconProps['name']
  /** Display an avatar on the left side. */
  avatar?: AvatarProps
  /** When `true`, the icon will be displayed on the left side. */
  leading?: boolean
  /**
   * Display an icon on the left side.
   * @IconifyIcon
   */
  leadingIcon?: IconProps['name']
  /** When `true`, the icon will be displayed on the right side. */
  trailing?: boolean
  /**
   * Display an icon on the right side.
   * @IconifyIcon
   */
  trailingIcon?: IconProps['name']
  /** When `true`, the loading icon will be displayed. */
  loading?: boolean
  /**
   * The icon when the `loading` prop is `true`.
   * @defaultValue appConfig.ui.icons.loading
   * @IconifyIcon
   */
  loadingIcon?: IconProps['name']
}

export function useComponentIcons(componentProps: MaybeRefOrGetter<UseComponentIconsProps>) {
  const appConfig = useAppConfig()

  const props = computed(() => toValue(componentProps))

  const isLeading = computed(() => (props.value.icon && props.value.leading) || (props.value.icon && !props.value.trailing) || (props.value.loading && !props.value.trailing) || !!props.value.leadingIcon)
  const isTrailing = computed(() => (props.value.icon && props.value.trailing) || (props.value.loading && props.value.trailing) || (!!props.value.trailingIcon && props.value.trailing !== false))

  const leadingIconName = computed(() => {
    if (props.value.loading) {
      return props.value.loadingIcon || appConfig.ui.icons.loading
    }

    return props.value.leadingIcon || props.value.icon
  })
  const trailingIconName = computed(() => {
    if (props.value.loading && !isLeading.value) {
      return props.value.loadingIcon || appConfig.ui.icons.loading
    }

    return props.value.trailingIcon || props.value.icon
  })

  return {
    isLeading,
    isTrailing,
    leadingIconName,
    trailingIconName
  }
}

import type { ComputedRef, VNode } from 'vue'
import { computed, getCurrentInstance } from 'vue'
import defu from 'defu'
import { createContext } from 'reka-ui'
import { useAppConfig } from '@/lib/nuxt/imports'
import { get } from '../utils'

export type ThemeContext = {
  defaults: ComputedRef<Record<string, Record<string, any> | undefined>>
}

const [_injectThemeContext, provideThemeContext] = createContext<ThemeContext>('UTheme', 'RootContext')

/**
 * Module-level fallback so components can call `useComponentProps` outside any
 * `<UTheme>` wrapper without crashing.
 */
export const defaultThemeContext: ThemeContext = {
  defaults: computed(() => ({}))
}

export function injectThemeContext(fallback: ThemeContext = defaultThemeContext): ThemeContext {
  return _injectThemeContext(fallback)
}

export { provideThemeContext }

function camelCase(str: string): string {
  return str.replace(/-(\w)/g, (_, c: string) => c.toUpperCase())
}

function kebabCase(str: string): string {
  return str.replace(/[A-Z]/g, c => `-${c.toLowerCase()}`)
}

/**
 * Vuetify-style detection for whether a prop was explicitly passed by the parent,
 * distinguishing "user set it" from "got the `withDefaults` fallback".
 * Checks both camelCase and kebab-case names to cover both template conventions.
 */
function propIsDefined(vnode: VNode | null | undefined, prop: string): boolean {
  if (!vnode || !vnode.props) return false
  return vnode.props[camelCase(prop)] !== undefined
    || vnode.props[kebabCase(prop)] !== undefined
}

/**
 * Resolve a component's props with the priority chain:
 *   explicit prop > nearest UTheme > app.config.ui.<name>.defaultVariants
 *     > withDefaults
 *
 * The returned proxy transparently reads from `props`, falling through to the
 * injected `ThemeContext` and `app.config.ui.<name>.defaultVariants` for
 * defaults. The component's tv() `defaultVariants` are intentionally left out
 * of the proxy fallback — they continue to drive `tv()`-internal class
 * resolution (the original semantics) without leaking into prop reads. The
 * `ui` and `class` props are merged (explicit classes override theme classes)
 * instead of being replaced.
 */
export function useComponentProps<T extends object>(name: string, props: T): T {
  const vm = getCurrentInstance()
  const { defaults } = injectThemeContext()
  const appConfig = useAppConfig() as { ui?: Record<string, any> }

  return new Proxy(props, {
    get(target, prop, receiver) {
      // Advertise as a Vue reactive proxy so `toRefs`, `reactiveOmit`,
      // `reactivePick`, and similar utilities don't warn when given the proxy.
      // Reads still flow through to the underlying reactive `props` object
      // returned by `defineProps`, so reactivity tracking works normally.
      if (prop === '__v_isReactive') return true
      if (prop === '__v_raw') return target

      const raw = Reflect.get(target, prop, receiver)
      if (typeof prop !== 'string') return raw

      // Support dotted-path names (e.g. `prose.p`, `prose.code`) so prose
      // components can pull from the same nested `ThemeContext.defaults` shape
      // that `normalizeUi` produces in `<UTheme>`.
      const themeEntry = name.includes('.') ? get(defaults.value, name) : defaults.value[name]

      if (prop === 'ui') {
        const themeUi = themeEntry?.ui
        if (!raw && !themeUi) return raw
        return defu(raw ?? {}, themeUi ?? {})
      }

      // Like `ui`, `class` is merged instead of replaced so a component passing
      // its own `class` still gets the theme classes. The explicit class comes
      // last to win `twMerge`'s last-in-wins resolution.
      if (prop === 'class') {
        const themeClass = themeEntry?.class
        if (themeClass === undefined) return raw
        if (raw === undefined) return themeClass
        return [themeClass, raw]
      }

      if (vm && propIsDefined(vm.vnode, prop)) return raw

      const themeValue = themeEntry?.[prop]
      if (themeValue !== undefined) return themeValue

      // A global `app.config.ui.<name>.defaultVariants` value takes priority over
      // the component's `withDefaults` fallback. This keeps `defaultVariants`
      // working uniformly for every variant, including props a component pins in
      // `withDefaults` (e.g. `orientation`, kept defined so `:data-orientation`
      // always renders a value).
      const appConfigEntry = name.includes('.') ? get(appConfig.ui ?? {}, name) : appConfig.ui?.[name]
      const appConfigValue = appConfigEntry?.defaultVariants?.[prop]
      if (appConfigValue !== undefined) return appConfigValue

      // Only fall back to `raw` when `withDefaults` set an explicit default for
      // this prop. Otherwise Vue's runtime would auto-cast unset Boolean props
      // to `false` (and other typed props to their normalized fallback), which
      // would override defaults baked into the underlying primitive when those
      // props are forwarded downstream.
      const propDef = (vm?.type as any)?.props?.[prop]
      if (propDef && Object.prototype.hasOwnProperty.call(propDef, 'default')) {
        return raw
      }

      return undefined
    },
    // `has`, `ownKeys`, and `getOwnPropertyDescriptor` reflect the underlying
    // `defineProps` schema only — theme defaults are NOT enumerable. As a
    // result, `Object.keys(props)`, `for…in`, and `{ ...props }` see only the
    // declared prop keys, but each value lookup still flows through the proxy.
    // This is the contract our internal `useForwardProps` relies on.
    has: (t, p) => Reflect.has(t, p),
    ownKeys: t => Reflect.ownKeys(t),
    getOwnPropertyDescriptor: (t, p) => Reflect.getOwnPropertyDescriptor(t, p)
  })
}

import type { InjectionKey, ComputedRef } from 'vue'
import { computed, defineComponent, inject, provide } from 'vue'
import type { FieldGroupProps } from '../../../components/kit/XFieldGroup.vue'
import type { GetObjectField } from '../types/utils'

export const fieldGroupInjectionKey: InjectionKey<ComputedRef<{
  size: FieldGroupProps['size']
  orientation: FieldGroupProps['orientation']
}>> = Symbol('nuxt-ui.field-group')

type Props<T> = {
  size?: GetObjectField<T, 'size'>
}

/**
 * Reads `size` / `orientation` from a wrapping `<XFieldGroup>` (or `<UButtonGroup>`, etc.).
 *
 * **Always pass the raw `_props`, never the `useComponentProps` proxy** — the
 * fallback `props?.size ?? fieldGroup?.value.size` must keep the closer context
 * winning over `<UTheme :props>`. To still apply theme defaults on bare inputs,
 * fall back to the proxy at the `tv()` call site: `size: groupSize.value ?? props.size`.
 */
export function useFieldGroup<T>(props: Props<T>) {
  const fieldGroup = inject(fieldGroupInjectionKey, undefined)
  return {
    orientation: computed(() => fieldGroup?.value.orientation),
    size: computed(() => props?.size ?? fieldGroup?.value.size)
  }
}

export const FieldGroupReset = defineComponent({
  name: 'FieldGroupReset',
  setup(_, { slots }) {
    provide(fieldGroupInjectionKey, computed(() => ({
      size: undefined,
      orientation: undefined
    })))
    return () => slots.default?.()
  }
})

import type { ComponentPublicInstance, MaybeRef } from 'vue'
import { ref, computed, unref, onMounted, watch, reactive } from 'vue'
import { useFileDialog, useDropZone } from '@vueuse/core'

export interface UseFileUploadOptions {
  /**
   * Specifies the allowed file types. Provide a comma-separated list of MIME types or file extensions.
   * @see https://developer.mozilla.org/en-US/docs/Web/HTML/Reference/Attributes/accept
   * @defaultValue '*'
   */
  accept?: MaybeRef<string>
  reset?: MaybeRef<boolean>
  multiple?: MaybeRef<boolean>
  dropzone?: boolean
  onUpdate: (files: File[]) => void
}

function parseAcceptToDataTypes(accept: string): string[] {
  // An empty list means no restriction (`useDropZone` allows all types for an empty array).
  if (!accept || accept === '*') {
    return []
  }

  return accept
    .split(',')
    .map((type) => {
      const trimmedType = type.trim()

      if (trimmedType.includes('/') && trimmedType.endsWith('/*')) {
        return trimmedType.split('/')[0] || trimmedType
      }
      return trimmedType
    })
    .filter((type) => {
      return !type.startsWith('.')
    })
}

export function useFileUpload(options: UseFileUploadOptions) {
  const {
    accept = '*',
    reset = false,
    multiple = false,
    dropzone = true,
    onUpdate
  } = options
  const inputRef = ref<ComponentPublicInstance>()
  const dropzoneRef = ref<HTMLDivElement>()

  const dataTypes = computed<readonly string[]>(() => parseAcceptToDataTypes(unref(accept)))

  const onDrop = (files: FileList | File[] | null, fromDropZone = false) => {
    if (!files || files.length === 0) {
      return
    }
    if (files instanceof FileList) {
      files = Array.from(files)
    }
    if (files.length > 1 && !unref(multiple)) {
      files = [files[0]!]
    }

    // Sync dropped files to the input element for proper native validation
    if (fromDropZone && inputRef.value?.$el) {
      try {
        const dt = new DataTransfer()
        files.forEach(file => dt.items.add(file))
        inputRef.value.$el.files = dt.files
      } catch (e) {
        console.warn('Could not sync files to input element:', e)
      }
    }

    onUpdate(files)
  }

  const isDragging = ref(false)
  const fileDialog = reactive({
    open: () => {
    }
  })

  function open() {
    fileDialog.open()
  }

  onMounted(() => {
    const { isOverDropZone } = dropzone
      ? useDropZone(dropzoneRef, { dataTypes, onDrop: files => onDrop(files, true) })
      : { isOverDropZone: ref(false) }

    watch(isOverDropZone, (value) => {
      isDragging.value = value
    })

    const { onChange, open } = useFileDialog({
      accept,
      multiple,
      input: computed(() => unref(inputRef)?.$el),
      reset
    })

    fileDialog.open = open

    onChange(fileList => onDrop(fileList, false))
  })

  return {
    isDragging,
    open,
    inputRef,
    dropzoneRef
  }
}

import { useFilter as useRekaFilter } from 'reka-ui'
import { get } from '../utils'

export function useFilter() {
  const { contains, startsWith } = useRekaFilter({ sensitivity: 'base' })

  /**
   * Score a string match against a search term.
   * @returns 0 = exact, 1 = starts with, 2 = contains, null = no match
   */
  function score(value: string, searchTerm: string): number | null {
    if (!contains(value, searchTerm)) return null
    if (contains(searchTerm, value)) return 0
    if (startsWith(value, searchTerm)) return 1
    return 2
  }

  /**
   * Score an item (primitive or object) against a search term.
   * For objects, returns the best score across all specified fields.
   * Supports array field values (each element is scored independently).
   * @returns 0 = exact, 1 = starts with, 2 = contains, null = no match
   */
  function scoreItem(item: any, searchTerm: string, fields: string[]): number | null {
    if (typeof item !== 'object' || item === null) {
      return score(String(item), searchTerm)
    }

    let bestScore: number | null = null
    for (const field of fields) {
      const value = get(item, field)
      if (value == null) continue

      const values = Array.isArray(value) ? value.map(String) : [String(value)]
      for (const v of values) {
        const s = score(v, searchTerm)
        if (s !== null && (bestScore === null || s < bestScore)) bestScore = s
        if (bestScore === 0) return 0
      }
    }
    return bestScore
  }

  /**
   * Filter and sort a flat list of items by match quality.
   * Returns a new array with only matching items, sorted by relevance (exact > startsWith > contains).
   */
  function filter<T>(items: T[], searchTerm: string, fields: string[]): T[] {
    if (!searchTerm) return items

    const scored: { item: T, score: number }[] = []
    for (const item of items) {
      const s = scoreItem(item, searchTerm, fields)
      if (s !== null) {
        scored.push({ item, score: s })
      }
    }

    scored.sort((a, b) => a.score - b.score)
    return scored.map(({ item }) => item)
  }

  /**
   * Filter and sort grouped items by match quality, preserving group structure.
   * Structural items (labels, separators) are kept at their relative position.
   * Empty groups (containing only structural items) are removed.
   */
  function filterGroups<T>(
    groups: T[][],
    searchTerm: string,
    options: {
      fields: string[]
      isStructural?: (item: T) => boolean
    }
  ): T[][] {
    if (!searchTerm) return groups

    return groups.map((group) => {
      const result: { item: T, score: number }[] = []
      for (const item of group) {
        if (item === undefined || item === null) continue
        if (options.isStructural?.(item)) {
          result.push({ item, score: -1 })
          continue
        }
        const s = scoreItem(item, searchTerm, options.fields)
        if (s !== null) {
          result.push({ item, score: s })
        }
      }
      // Sort each run of matches on its own so items never cross a label or separator.
      let start = 0
      for (let i = 0; i <= result.length; i++) {
        if (i === result.length || result[i]!.score === -1) {
          result.splice(start, i - start, ...result.slice(start, i).sort((a, b) => a.score - b.score))
          start = i + 1
        }
      }
      return result.map(({ item }) => item)
    }).filter(group => group.some(item => !options.isStructural?.(item)))
  }

  return { score, scoreItem, filter, filterGroups }
}

import { inject, computed, provide, getCurrentScope, onScopeDispose } from 'vue'
import type { InjectionKey, Ref, ComputedRef } from 'vue'
import { useDebounceFn } from '@vueuse/core'
import type { UseEventBusReturn } from '@vueuse/core'
import type { FormFieldProps } from '../../../components/kit/XFormField.vue'
import type { FormErrorWithId, FormEvent, FormInputEvents, FormFieldInjectedOptions, FormInjectedOptions } from '../types/form'
import type { GetObjectField } from '../types/utils'

type Props<T> = {
  id?: string
  name?: string
  size?: GetObjectField<T, 'size'>
  color?: GetObjectField<T, 'color'>
  highlight?: boolean
  disabled?: boolean
}

export const formOptionsInjectionKey: InjectionKey<ComputedRef<FormInjectedOptions>> = Symbol('nuxt-ui.form-options')
export const formBusInjectionKey: InjectionKey<UseEventBusReturn<FormEvent<any>, string>> = Symbol('nuxt-ui.form-events')
export const formStateInjectionKey: InjectionKey<ComputedRef<Record<string, any> | undefined>> = Symbol('nuxt-ui.form-state')
export const formFieldInjectionKey: InjectionKey<ComputedRef<FormFieldInjectedOptions<FormFieldProps>> | undefined> = Symbol('nuxt-ui.form-field')
export const inputIdInjectionKey: InjectionKey<Ref<string | undefined>> = Symbol('nuxt-ui.input-id')
export const formInputsInjectionKey: InjectionKey<Ref<Record<string, { id?: string, pattern?: RegExp }>>> = Symbol('nuxt-ui.form-inputs')
export const formLoadingInjectionKey: InjectionKey<Readonly<Ref<boolean>>> = Symbol('nuxt-ui.form-loading')
export const formErrorsInjectionKey: InjectionKey<Readonly<Ref<FormErrorWithId[]>>> = Symbol('nuxt-ui.form-errors')

/**
 * Wires an input to its wrapping `<XFormField>` (id/name/aria, validation events, error-driven color).
 *
 * **Always pass the raw `_props`, never the `useComponentProps` proxy.**
 * The internal fallback `props?.x ?? formField?.value.x` must distinguish
 * "explicit prop" from "theme default" — passing the proxy would leak
 * `<UTheme :props>` defaults into the explicit slot and let theme size/color
 * silently override the wrapping field (regression-tested in `Theme.spec.ts`).
 *
 * To get `<UTheme :props>` to apply when no `<XFormField>` wraps the input,
 * fall back to the proxy at the `tv()` call site:
 *
 * ```ts
 * size: size.value ?? props.size,
 * color: color.value ?? props.color,
 * highlight: highlight.value ?? props.highlight,
 * disabled: disabled.value ?? props.disabled
 * ```
 *
 * `highlight` and `disabled` are Boolean props, which Vue auto-casts to `false`
 * when unset, so they are normalized back to `undefined` here. Otherwise the
 * `??` above would short-circuit on `false` and the proxy would never be read.
 *
 * Final precedence: `explicit > FormField > <UTheme :props> > app.config > withDefaults > tv defaults`,
 * matching what `useComponentProps` resolves.
 */
export function useFormField<T>(props?: Props<T>, opts?: { bind?: boolean, deferInputValidation?: boolean }) {
  const formOptions = inject(formOptionsInjectionKey, undefined)
  const formBus = inject(formBusInjectionKey, undefined)
  const formField = inject(formFieldInjectionKey, undefined)
  const inputId = inject(inputIdInjectionKey, undefined)

  // Blocks the FormField injection to avoid duplicating events when nesting input components.
  provide(formFieldInjectionKey, undefined)

  if (formField && inputId) {
    if (opts?.bind === false) {
      // Removes for="..." attribute on label for RadioGroup and alike.
      inputId.value = undefined
    } else if (props?.id) {
      // Updates for="..." attribute on label if props.id is provided.
      inputId.value = props?.id
    }
  }

  function emitFormEvent(type: FormInputEvents, name?: string, eager?: boolean) {
    if (formBus && formField && name) {
      formBus.emit({ type, name, eager })
    }
  }

  function emitFormBlur() {
    emitFormEvent('blur', formField?.value.name)
  }

  function emitFormFocus() {
    emitFormEvent('focus', formField?.value.name)
  }

  function emitFormChange() {
    emitFormEvent('change', formField?.value.name)
  }

  // The trailing call still fires after teardown, which would validate a field
  // that is no longer rendered when the input unmounts inside the debounce window.
  let disposed = false
  if (getCurrentScope()) {
    onScopeDispose(() => {
      disposed = true
    })
  }

  const emitFormInput = useDebounceFn(
    () => {
      if (disposed) return

      emitFormEvent('input', formField?.value.name, !opts?.deferInputValidation || formField?.value.eagerValidation)
    },
    formField?.value.validateOnInputDelay ?? formOptions?.value.validateOnInputDelay ?? 0
  )

  return {
    id: computed(() => props?.id ?? inputId?.value),
    name: computed(() => props?.name ?? formField?.value.name),
    size: computed(() => props?.size ?? formField?.value.size),
    color: computed(() => formField?.value.error ? 'error' : props?.color),
    highlight: computed(() => formField?.value.error ? true : (props?.highlight || undefined)),
    disabled: computed(() => formOptions?.value.disabled || props?.disabled || undefined),
    emitFormBlur,
    emitFormInput,
    emitFormChange,
    emitFormFocus,
    ariaAttrs: computed(() => {
      if (!formField?.value) return

      const descriptiveAttrs = ['error' as const, 'hint' as const, 'description' as const, 'help' as const]
        .filter(type => formField?.value?.[type])
        .map(type => `${formField?.value.ariaId}-${type}`) || []

      const attrs: Record<string, any> = {
        'aria-invalid': !!formField?.value.error
      }

      if (descriptiveAttrs.length > 0) {
        attrs['aria-describedby'] = descriptiveAttrs.join(' ')
      }

      return attrs
    })
  }
}

import type { ComputedRef, MaybeRef } from 'vue'
import { computed, unref } from 'vue'
import { useEmitAsProps } from 'reka-ui'

/**
 * Proxy-aware replacement for reka-ui's `useForwardProps` / `useForwardPropsEmits`.
 * Forwards every enumerable key of `source` whose value is not `undefined`, and
 * — when `emits` is provided — merges the emit handlers as `onUpdate:open`-style
 * props on the resulting object.
 *
 * Unlike reka-ui's version, this does NOT filter by `vm.vnode.props` or
 * `vm.type.props.<key>.default`, so values supplied by `<UTheme :props>`
 * through `useComponentProps` flow through transparently to the underlying
 * Reka primitive.
 */
export function useForwardProps<T extends object, E extends string = string>(
  source: MaybeRef<T> | ComputedRef<T>,
  emits?: (event: E, ...args: any[]) => void
): ComputedRef<Partial<T>> {
  // reka-ui 2.10.0 tightened `useEmitAsProps` to require an `Emit<Name, Fn>` inferred
  // from a concrete `defineEmits` signature; our generic proxy emit doesn't satisfy it,
  // so cast at the call site (this is a runtime-transparent name → `onXxx` prop mapping).
  const emitAsProps = emits ? useEmitAsProps(emits as Parameters<typeof useEmitAsProps>[0]) : {}
  return computed(() => {
    const src = unref(source)
    const out: Record<string, any> = { ...emitAsProps }
    for (const key in src) {
      const value = (src as any)[key]
      if (value !== undefined) out[key] = value
    }
    return out as Partial<T>
  })
}

/**
 * Prevents Enter-to-submit from firing during IME composition.
 *
 * Handles the Safari quirk where `compositionend` fires before `keydown`,
 * making `event.isComposing` unreliable (https://bugs.webkit.org/show_bug.cgi?id=165004).
 */
export function useIMEGuard(callback: (event: KeyboardEvent) => void) {
  let compositionJustEnded = false

  function isComposing(event: KeyboardEvent) {
    return event.isComposing || event.keyCode === 229
  }

  function onKeydown(event: KeyboardEvent) {
    if (compositionJustEnded || isComposing(event)) {
      return
    }

    event.preventDefault()
    callback(event)
  }

  let compositionEndTimer: ReturnType<typeof setTimeout>

  function onCompositionEnd() {
    clearTimeout(compositionEndTimer)
    compositionJustEnded = true
    compositionEndTimer = setTimeout(() => {
      compositionJustEnded = false
    }, 50)
  }

  return { onKeydown, onCompositionEnd }
}

import { reactive, computed, onMounted } from 'vue'
import { createSharedComposable } from '@vueuse/core'

type KbdKeysSpecificMap = {
  meta: string
  alt: string
  ctrl: string
}

export const kbdKeysMap = {
  meta: '',
  ctrl: '',
  alt: '',
  win: '⊞',
  command: '⌘',
  shift: '⇧',
  control: '⌃',
  option: '⌥',
  enter: '↵',
  delete: '⌦',
  backspace: '⌫',
  escape: 'Esc',
  tab: '⇥',
  capslock: '⇪',
  arrowup: '↑',
  arrowright: '→',
  arrowdown: '↓',
  arrowleft: '←',
  pageup: '⇞',
  pagedown: '⇟',
  home: '↖',
  end: '↘'
}

export type KbdKey = keyof typeof kbdKeysMap
export type KbdKeySpecific = keyof KbdKeysSpecificMap

const _useKbd = () => {
  const macOS = computed(() => import.meta.client && navigator && navigator.userAgent && navigator.userAgent.match(/Macintosh;/))

  const kbdKeysSpecificMap = reactive({
    meta: ' ',
    alt: ' ',
    ctrl: ' '
  })

  onMounted(() => {
    kbdKeysSpecificMap.meta = macOS.value ? kbdKeysMap.command : 'Ctrl'
    kbdKeysSpecificMap.ctrl = macOS.value ? kbdKeysMap.control : 'Ctrl'
    kbdKeysSpecificMap.alt = macOS.value ? kbdKeysMap.option : 'Alt'
  })

  function getKbdKey(value?: KbdKey | string) {
    if (!value) {
      return
    }

    if (['meta', 'alt', 'ctrl'].includes(value)) {
      return kbdKeysSpecificMap[value as KbdKeySpecific]
    }

    return kbdKeysMap[value as KbdKey] || value
  }

  return {
    macOS,
    getKbdKey
  }
}

export const useKbd = /* @__PURE__ */ createSharedComposable(_useKbd)

