export type UseResizableProps = {
  /**
   * The id of the panel.
   * @defaultValue useId()
   */
  id?: string
  /**
   * The side to render the panel on.
   * @defaultValue 'left'
   */
  side?: 'left' | 'right'
  /**
   * The minimum size of the panel.
   * @defaultValue 0
   */
  minSize?: number
  /**
   * The maximum size of the panel.
   * @defaultValue 100
   */
  maxSize?: number
  /**
   * The default size of the panel.
   * @defaultValue 0
   */
  defaultSize?: number
  /**
   * Whether to allow the user to resize the panel.
   * @defaultValue true
   */
  resizable?: boolean
  /**
   * Whether to allow the user to collapse the panel.
   * @defaultValue true
   */
  collapsible?: boolean
  /**
   * The size of the panel when collapsed.
   * @defaultValue 0
   */
  collapsedSize?: number
  /**
   * The storage to use for the size.
   * @defaultValue 'cookie'
   */
  storage?: 'cookie' | 'local'
  /**
   * Unique id used to auto-save size.
   * @defaultValue 'dashboard'
   */
  storageKey?: string
  /**
   * Options to pass to the underlying storage (`useCookie` or `useStorage`).
   */
  storageOptions?: Record<string, any>
  /**
   * Whether to persist the size in the storage.
   * @defaultValue true
   */
  persistent?: boolean
