export type UseResizableReturn = {
  el: Ref<HTMLElement | null>
  size: Ref<number>
  isDragging: Ref<boolean>
  isCollapsed: Ref<boolean>
  onMouseDown: (e: MouseEvent) => void
  onTouchStart: (e: TouchEvent) => void
  onDoubleClick: (e: MouseEvent) => void
  collapse: (value?: boolean) => void
}

export function useResizable(key: string, options: Ref<UseResizableProps> | UseResizableProps = {}, { collapsed = ref(false) }: { collapsed?: Ref<boolean> } = {}): UseResizableReturn {
  const el = ref<HTMLElement | null>(null)
  const opts = computed(() => ({
    side: 'left',
    minSize: 0,
    maxSize: 100,
    defaultSize: 0,
    storage: 'cookie',
    persistent: true,
    collapsible: false,
    collapsedSize: 0,
    resizable: true,
    unit: '%',
    ...unref(options)
  }))

  const { dir } = useLocale()

  type StorageType = {
    size: number
    collapsed: boolean
  }

  const defaultStorageValue = {
    size: opts.value.defaultSize,
    collapsed: unref(collapsed) ?? false
  }

  const storageData = (opts.value.persistent && (opts.value.resizable || opts.value.collapsible))
    ? opts.value.storage === 'cookie'
      ? useCookie<StorageType>(key, { ...opts.value.storageOptions, default: () => defaultStorageValue })
      : useStorage<StorageType>(key, defaultStorageValue, undefined, opts.value.storageOptions)
    : ref(defaultStorageValue)

  // A persisted `null` (corrupted cookie/localStorage or cookie removed at runtime) bypasses
  // the storage defaults and would crash every access, so guard reads and heal on write (#6517).
  const writeStorage = (patch: Partial<StorageType>) => {
    if (storageData.value) {
      Object.assign(storageData.value, patch)
    } else {
      storageData.value = { ...defaultStorageValue, ...patch }
    }
  }

  const isCollapsed = computed({
    get: () => storageData.value?.collapsed ?? defaultStorageValue.collapsed,
    set: (value: boolean) => {
      if (!opts.value.collapsible) {
        return
      }

      if (isRef(collapsed)) {
        collapsed.value = value
      }
      writeStorage({ collapsed: value })
    }
  })

  const previousSize = ref(opts.value.defaultSize)

  const size = computed({
    get: () => storageData.value?.size ?? opts.value.defaultSize,
    set: (value) => {
      writeStorage({ size: value })
    }
  })

  const currentSize = computed(() => isCollapsed.value ? opts.value.collapsedSize : size.value)

  const isDragging = ref(false)

  // Read once per drag: `getComputedStyle` on every pointer move forces a style recalc.
  const getRootFontSize = () => opts.value.unit === 'rem' ? Number.parseFloat(getComputedStyle(document.documentElement).fontSize) : 1

  const resize = (clientX: number, initialPos: number, initialSize: number, rootFontSize: number): void => {
    if (!el.value || !opts.value.resizable) {
      return
    }

    const parentSize = el.value.parentElement?.offsetWidth || 1
    const isRtl = dir.value === 'rtl'

    // In RTL mode, we need to invert the delta calculation
    let delta: number
    if (isRtl) {
      delta = opts.value.side === 'left' ? initialPos - clientX : clientX - initialPos
    } else {
      delta = opts.value.side === 'left' ? clientX - initialPos : initialPos - clientX
    }

    const newSize = initialSize + delta

    // Calculate size based on the selected unit
    let newValue: number
    if (opts.value.unit === 'rem') {
      // Convert pixels to rem
      newValue = newSize / rootFontSize
    } else if (opts.value.unit === 'px') {
      // Use pixel value directly
      newValue = newSize
    } else {
      // Default percentage calculation
      newValue = (newSize / parentSize) * 100
    }

    // Auto collapse when dragging near collapsedSize
    if (opts.value.collapsible && newValue < (opts.value.collapsedSize + 4)) {
      collapse(true)
      return
    } else if (isCollapsed.value) {
      collapse(false)
    }

    size.value = Math.min(opts.value.maxSize, Math.max(opts.value.minSize, newValue))
  }

  const onMouseDown = (e: MouseEvent) => {
    if (!el.value || !opts.value.resizable) {
      return
    }

    e.preventDefault()
    e.stopPropagation()

    const elWidth = el.value.getBoundingClientRect().width
    if (!elWidth) {
      return
    }

    const initialX = e.clientX
    const initialWidth = elWidth
    const rootFontSize = getRootFontSize()

    isDragging.value = true

    const handleMouseMove = (e: MouseEvent) => {
      resize(e.clientX, initialX, initialWidth, rootFontSize)
    }

    const handleMouseUp = () => {
      isDragging.value = false
      document.removeEventListener('mousemove', handleMouseMove)
      document.removeEventListener('mouseup', handleMouseUp)
    }

    document.addEventListener('mousemove', handleMouseMove)
    document.addEventListener('mouseup', handleMouseUp)
  }

  const onTouchStart = (e: TouchEvent) => {
    if (!el.value || !opts.value.resizable || !e.touches[0]) {
      return
    }

    e.preventDefault()
    e.stopPropagation()

    const elWidth = el.value.getBoundingClientRect().width
    if (!elWidth) {
      return
    }

    const initialX = e.touches[0].clientX
    const initialWidth = elWidth
    const rootFontSize = getRootFontSize()

    isDragging.value = true

    const handleTouchMove = (e: TouchEvent) => {
      if (e.touches[0]) {
        resize(e.touches[0].clientX, initialX, initialWidth, rootFontSize)
      }
    }

    const handleTouchEnd = () => {
      isDragging.value = false
      document.removeEventListener('touchmove', handleTouchMove)
      document.removeEventListener('touchend', handleTouchEnd)
      document.removeEventListener('touchcancel', handleTouchEnd)
    }

    document.addEventListener('touchmove', handleTouchMove, { passive: false })
    document.addEventListener('touchend', handleTouchEnd)
    document.addEventListener('touchcancel', handleTouchEnd)
  }

  const onDoubleClick = (e: MouseEvent) => {
    if (!el.value || !opts.value.resizable) {
      return
    }

    e.preventDefault()
    e.stopPropagation()

    if (isCollapsed.value) {
      collapse(false)
    }

    size.value = opts.value.defaultSize
  }

  const collapse = (value?: boolean) => {
    if (!opts.value.collapsible) {
      return
    }

    const newCollapsed = value ?? !isCollapsed.value
    if (newCollapsed && !isCollapsed.value) {
      previousSize.value = size.value
    } else if (!newCollapsed && isCollapsed.value) {
      size.value = previousSize.value
    }

    isCollapsed.value = newCollapsed
  }

  // Initial sync of storage value to external collapsed ref
  if (isRef(collapsed) && storageData.value?.collapsed) {
    collapsed.value = storageData.value.collapsed
  }

  // Watch for changes in the external collapsed ref
  if (isRef(collapsed)) {
    watch(collapsed, (value) => {
      if (!opts.value.collapsible) {
        return
      }

      if (storageData.value?.collapsed !== value) {
        isCollapsed.value = value
      }
    })
  }

  return {
    el,
    size: currentSize,
    isDragging,
    isCollapsed,
    onMouseDown,
    onTouchStart,
    onDoubleClick,
    collapse
  }
}

import type { CSSProperties, MaybeRef, MaybeRefOrGetter } from 'vue'
import { computed, toValue } from 'vue'
import { useScroll } from '@vueuse/core'

export interface UseScrollShadowOptions {
  /**
   * The shadow size in pixels.
   * @defaultValue 24
   */
  size?: MaybeRefOrGetter<number>
  /**
   * The scroll direction to apply shadows.
   * @defaultValue 'vertical'
   */
  orientation?: MaybeRefOrGetter<'vertical' | 'horizontal'>
}

export function useScrollShadow(element: MaybeRef<HTMLElement | null | undefined>, options: UseScrollShadowOptions = {}) {
  const { arrivedState } = useScroll(element)

  const style = computed<CSSProperties | undefined>(() => {
    const el = toValue(element)
    const orientation = toValue(options.orientation) ?? 'vertical'
    const [startKey, endKey] = orientation === 'horizontal' ? ['left', 'right'] as const : ['top', 'bottom'] as const

    const showStart = !arrivedState[startKey]
    const showEnd = !arrivedState[endKey]

    if (!showStart && !showEnd) return undefined

    const overflows = el
      ? orientation === 'horizontal' ? el.scrollWidth > el.clientWidth : el.scrollHeight > el.clientHeight
      : false
    if (!overflows) return undefined

    const size = `${toValue(options.size) ?? 24}px`

    const angle = orientation === 'horizontal' ? '90deg' : '180deg'

    if (showStart && showEnd) {
      return { maskImage: `linear-gradient(${angle}, transparent, #000 ${size}, #000 calc(100% - ${size}), transparent)` }
    }
    if (showStart) {
      return { maskImage: `linear-gradient(${angle}, transparent, #000 ${size})` }
    }
    return { maskImage: `linear-gradient(${angle}, #000, #000 calc(100% - ${size}), transparent)` }
  })

  const isOverflowing = computed(() => {
    // Read arrivedState to establish reactive dependency on scroll events
    void (arrivedState.top, arrivedState.bottom, arrivedState.left, arrivedState.right)

    const el = toValue(element)
    if (!el) return false

    const orientation = toValue(options.orientation) ?? 'vertical'
    return orientation === 'horizontal'
      ? el.scrollWidth > el.clientWidth
      : el.scrollHeight > el.clientHeight
  })

  return {
    style,
    isOverflowing,
    arrivedState
  }
}

import { ref, watch, onBeforeMount, onBeforeUnmount } from 'vue'

export function useScrollspy() {
  const observer = ref<IntersectionObserver>()
  const visibleHeadings = ref<string[]>([])
  const activeHeadings = ref<string[]>([])

  function observerCallback(entries: IntersectionObserverEntry[]) {
    // Batched into a single write so the watcher runs once per callback, not once per entry.
    const headings = new Set(visibleHeadings.value)
    let changed = false

    for (const entry of entries) {
      const id = entry.target.id
      if (!id) {
        continue
      }

      if (entry.isIntersecting) {
        if (!headings.has(id)) {
          headings.add(id)
          changed = true
        }
      } else if (headings.delete(id)) {
        changed = true
      }
    }

    if (changed) {
      visibleHeadings.value = [...headings]
    }
  }

  function updateHeadings(headings: Element[]) {
    if (!observer.value) {
      return
    }

    // Drop previously observed targets so repeated calls (e.g. on page navigation) don't accumulate.
    observer.value.disconnect()
    visibleHeadings.value = []

    headings.forEach(heading => observer.value!.observe(heading))
  }

  watch(visibleHeadings, (val, oldVal) => {
    if (val.length === 0) {
      activeHeadings.value = oldVal
    } else {
      activeHeadings.value = val
    }
  })

  // Create intersection observer
  onBeforeMount(() => (observer.value = new IntersectionObserver(observerCallback)))

  // Destroy it
  onBeforeUnmount(() => observer.value?.disconnect())

  return {
    visibleHeadings,
    activeHeadings,
    updateHeadings
  }
}

import type { Ref, InjectionKey } from 'vue'
import { ref, nextTick, inject } from 'vue'
import { useState } from '@/lib/nuxt/imports'
import type { ToastProps, ToastEmits } from '../../../components/kit/XToast.vue'
import type { EmitsToProps } from '../types/utils'

export const toastMaxInjectionKey: InjectionKey<Ref<number | undefined>> = Symbol('nuxt-ui.toast-max')

export interface Toast extends Omit<ToastProps, 'defaultOpen'>, EmitsToProps<ToastEmits> {
  id: string | number
  onClick?: (toast: Toast) => void
  /** @internal */
  _duplicate?: number
  /** @internal */
  _updated?: boolean
}

export function useToast() {
  const toasts = useState<Toast[]>('toasts', () => []) as Ref<Toast[]>
  const max = inject(toastMaxInjectionKey, undefined)

  const running = ref(false)
  const queue: Toast[] = []

  const generateId = () => `${Date.now()}-${Math.random().toString(36).slice(2, 9)}`

  function mergeDuplicate(index: number, toast: Toast) {
    toasts.value[index] = {
      ...toasts.value[index] as Toast,
      ...toast,
      _duplicate: ((toasts.value[index] as Toast)._duplicate || 0) + 1
    }
  }

  async function processQueue() {
    if (running.value || queue.length === 0) {
      return
    }

    running.value = true

    while (queue.length > 0) {
      await nextTick()

      const toast = queue.shift()!
      const maxValue = max?.value ?? 5
      if (maxValue <= 0) {
        if (toasts.value.length) {
          toasts.value = []
        }
        continue
      }

      // Dedupe at display time so duplicate ids merge no matter which `useToast()` instance queued them.
      const existingIndex = toasts.value.findIndex((t: Toast) => t.id === toast.id)
      if (existingIndex !== -1) {
        mergeDuplicate(existingIndex, toast)
        continue
      }

      toasts.value = [...toasts.value, toast].slice(-maxValue)
    }

    running.value = false
  }

  function add(toast: Partial<Toast>): Toast {
    const body = {
      id: generateId(),
      open: true,
      ...toast
    } as Toast

    const existingIndex = toasts.value.findIndex((t: Toast) => t.id === body.id)
    if (existingIndex !== -1) {
      mergeDuplicate(existingIndex, body)

      return body
    }

    queue.push(body)

    processQueue()

    return body
  }

  function update(id: string | number, toast: Omit<Partial<Toast>, 'id'>) {
    const index = toasts.value.findIndex((t: Toast) => t.id === id)
    if (index !== -1) {
      toasts.value[index] = {
        ...toasts.value[index] as Toast,
        ...toast,
        duration: toast.duration,
        open: true,
        _updated: true
      }

      nextTick(() => {
        const i = toasts.value.findIndex((t: Toast) => t.id === id)
        if (i !== -1 && toasts.value[i]!._updated) {
          toasts.value[i] = {
            ...toasts.value[i] as Toast,
            _updated: undefined
          }
        }
      })
    }
  }

  function remove(id: string | number) {
    const index = toasts.value.findIndex((t: Toast) => t.id === id)
    if (index !== -1 && toasts.value[index]!._updated) {
      return
    }

    if (index !== -1) {
      toasts.value[index] = {
        ...toasts.value[index] as Toast,
        open: false
      }
    }

    setTimeout(() => {
      toasts.value = toasts.value.filter((t: Toast) => t.id !== id)
    }, 200)
  }

  function clear() {
    toasts.value = []
  }

  return {
    toasts,
    add,
    update,
    remove,
    clear
  }
}

import { ref, computed, toValue, nextTick, watch } from 'vue'
import type { MaybeRefOrGetter, Ref, ComputedRef } from 'vue'
import type { ReferenceElement } from 'reka-ui'

export interface TourStep {
  /**
   * The element this step points to. Accepts:
   * - a CSS selector (`'#id'`, `'.class'`, or a bare id resolved as `#id`)
   * - an element or a virtual element (anything with `getBoundingClientRect`)
   * - a ref or a getter returning any of the above
   *
   * Omit or pass `null` to anchor the step to the center of the viewport
   * (useful for intro / summary steps with no target).
   */
  target?: MaybeRefOrGetter<string | ReferenceElement | null | undefined>
  /**
   * Any other fields (title, body, side, …) are passed through untouched
   * and available via `current` — you own the rendering and copy.
   */
  [key: string]: any
}

export interface UseTourOptions {
  /**
   * The step index the tour starts on.
   * @defaultValue 0
   */
  initialStep?: number
  /**
   * Loop back to the first step after the last one.
   * @defaultValue false
   */
  loop?: boolean
  /**
   * Scroll the target into view when a step becomes active.
   * @defaultValue true
   */
  scrollIntoView?: boolean | ScrollIntoViewOptions
}

export interface UseTourReturn {
  /** Whether the tour is currently open. */
  open: Ref<boolean>
  /** The current step index (clamped to the steps range). */
  index: Ref<number>
  /** The current step object, or `undefined` when there are no steps. */
  current: ComputedRef<TourStep | undefined>
  /** The resolved anchor for the current step, to pass to `<XPopover :reference>`. */
  reference: ComputedRef<ReferenceElement | undefined>
  /** Total number of steps. */
  total: ComputedRef<number>
  /** Whether a next step exists. */
  hasNext: ComputedRef<boolean>
  /** Whether a previous step exists. */
  hasPrev: ComputedRef<boolean>
  /** Open the tour, optionally at a given index. */
  start: (index?: number) => void
  /** Go to the next step (loops or finishes at the end depending on `loop`). */
  next: () => void
  /** Go to the previous step. */
  prev: () => void
  /** Jump to a specific step and open the tour. */
  goTo: (index: number) => void
  /** Close the tour. */
  finish: () => void
}

/**
 * Drive a guided tour with a single `<XPopover>` whose anchor moves between steps.
 *
 * @example
 * ```ts
 * const tour = useTour([
 *   { target: '#cta', title: 'Get started' },
 *   { target: () => card.value, title: 'Profile', side: 'right' },
 *   { target: null, title: 'All set' } // centered, no target
 * ])
 * ```
 * ```vue
 * <XPopover :open="tour.open.value" :reference="tour.reference.value">
 *   <template #content>…your content + buttons…</template>
 * </XPopover>
 * ```
 */
export function useTour(steps: MaybeRefOrGetter<TourStep[]>, options: UseTourOptions = {}): UseTourReturn {
  const { loop = false, scrollIntoView = true } = options

  const stepList = computed<TourStep[]>(() => toValue(steps) ?? [])
  const total = computed(() => stepList.value.length)

  const open = ref(false)
  const rawIndex = ref(options.initialStep ?? 0)

  function clamp(value: number): number {
    return Math.min(Math.max(value, 0), Math.max(total.value - 1, 0))
  }

  const index = computed<number>({
    get: () => clamp(rawIndex.value),
    set: value => (rawIndex.value = clamp(value))
  })

  const current = computed(() => stepList.value[index.value])
  const hasNext = computed(() => index.value < total.value - 1)
  const hasPrev = computed(() => index.value > 0)

  // A virtual element centered in the viewport, for steps without a target.
  const centerAnchor: ReferenceElement = {
    getBoundingClientRect() {
      const x = typeof window === 'undefined' ? 0 : window.innerWidth / 2
      const y = typeof window === 'undefined' ? 0 : window.innerHeight / 2
      return { x, y, top: y, left: x, right: x, bottom: y, width: 0, height: 0, toJSON: () => ({}) } as DOMRect
    }
  }

  const reference = computed<ReferenceElement | undefined>(() => {
    if (!open.value || typeof window === 'undefined') {
      return undefined
    }

    const target = toValue(current.value?.target)
    if (target == null) {
      return centerAnchor
    }

    if (typeof target === 'string') {
      const selector = target.startsWith('#') || target.startsWith('.') ? target : `#${target}`
      try {
        return (document.querySelector(selector) as ReferenceElement | null) ?? undefined
      } catch {
        // Ignore malformed selectors and leave the step unanchored.
        return undefined
      }
    }

    return target
  })

  function scrollTargetIntoView() {
    if (!scrollIntoView) {
      return
    }
    const el = reference.value
    if (el instanceof Element) {
      el.scrollIntoView(typeof scrollIntoView === 'object' ? scrollIntoView : { behavior: 'smooth', block: 'center' })
    }
  }

  function goTo(value: number) {
    index.value = value
    // Don't open with nothing to show — the `total` watcher only reacts to changes,
    // so it can't catch a tour that is started while already empty.
    if (total.value > 0) {
      open.value = true
    }
  }

  function start(value: number = options.initialStep ?? 0) {
    goTo(value)
  }

  function next() {
    if (hasNext.value) {
      index.value++
    } else if (loop) {
      index.value = 0
    } else {
      finish()
    }
  }

  function prev() {
    if (hasPrev.value) {
      index.value--
    }
  }

  function finish() {
    open.value = false
  }

  // Close automatically if the steps disappear while open.
  watch(total, (value) => {
    if (!value) {
      open.value = false
    }
  })

  // Scroll the active target into view on open / step change.
  watch([open, index], () => {
    if (open.value) {
      nextTick(scrollTargetIntoView)
    }
  })

  return {
    open,
    index,
    current,
    reference,
    total,
    hasNext,
    hasPrev,
    start,
    next,
    prev,
    goTo,
    finish
  }
}

