/** ai SDK 未随包安装，本地宽松类型替代（仅类型层） */
type UIMessage = { id: string; parts: Array<{ type: string; text?: string; state?: string }> }

/**
 * Extracts and concatenates all text parts from a UIMessage.
 *
 * @warning Do not use the output directly with MDC or v-html for user messages,
 * as this can lead to XSS vulnerabilities. For rendering, iterate over message.parts
 * and only render assistant messages with MDC.
 */
export function getTextFromMessage(message: UIMessage) {
  return message.parts
    .filter(part => part.type === 'text')
    .map(part => part.text)
    .join('')
}

/**
 * Checks if a text or reasoning part is currently being streamed.
 */
export function isPartStreaming(part: { state?: string }): boolean {
  return part.state === 'streaming'
}

/**
 * Checks if a tool part is still streaming (hasn't reached a terminal state
 * and isn't paused waiting for a user approval).
 *
 * Terminal states are `output-available`, `output-error`, and `output-denied`,
 * `approval-requested` is a paused state.
 */
export function isToolStreaming(part: { state: string }): boolean {
  return !['approval-requested', 'output-available', 'output-error', 'output-denied'].includes(part.state)
}

/**
 * Checks if a tool part is waiting for a user approval response.
 */
export function isToolApprovalPending(part: { state: string }): boolean {
  return part.state === 'approval-requested'
}

/**
 * Checks if a reasoning part is currently being streamed.
 *
 * @deprecated Use `isPartStreaming` instead.
 */
export function isReasoningStreaming(
  message: UIMessage,
  partIndex: number,
  chat: { status: string, messages: UIMessage[] }
): boolean {
  if (chat.status !== 'streaming') return false
  if (message.id !== chat.messages.at(-1)?.id) return false
  if (partIndex < 0 || partIndex >= message.parts.length) return false

  const partType = message.parts[partIndex]!.type
  for (let i = partIndex + 1; i < message.parts.length; i++) {
    if (message.parts[i]!.type !== partType) return false
  }
  return true
}

import { toRaw } from 'vue'
import type { FormSchema, StandardSchemaV1, Struct, ValidateReturnSchema } from '../types/form'

export function isSuperStructSchema(schema: any): schema is Struct<any, any> {
  return (
    'schema' in schema
    && typeof schema.coercer === 'function'
    && typeof schema.validator === 'function'
    && typeof schema.refiner === 'function'
  )
}

export function isStandardSchema(schema: any): schema is StandardSchemaV1 {
  return '~standard' in schema
}

export async function validateStandardSchema(
  state: any,
  schema: StandardSchemaV1
): Promise<ValidateReturnSchema<typeof state>> {
  const result = await schema['~standard'].validate(state)

  if (result.issues) {
    return {
      errors: result.issues?.map(issue => ({
        name: issue.path?.map(item => typeof item === 'object' ? item.key : item).join('.') || '',
        message: issue.message
      })) || [],
      result: null
    }
  }

  return {
    errors: null,
    result: result.value
  }
}

async function validateSuperstructSchema(state: any, schema: Struct<any, any>): Promise<ValidateReturnSchema<typeof state>> {
  const [err, result] = schema.validate(state)
  if (err) {
    const errors = err.failures().map(error => ({
      message: error.message,
      name: error.path.join('.')
    }))

    return {
      errors,
      result: null
    }
  }

  return {
    errors: null,
    result
  }
}

export function validateSchema<T extends object>(state: T, _schema: FormSchema<T>): Promise<ValidateReturnSchema<typeof state>> {
  // Schemas stored in reactive state reach us as Vue proxies. Zod 4.5 resolves
  // `~standard` through a lazy getter that captures the proxy as `this`, then
  // reads its non-configurable `_zod` internals through it, which violates the
  // proxy invariant and throws.
  const schema = toRaw(_schema)

  if (isStandardSchema(schema)) {
    return validateStandardSchema(state, schema)
  } else if (isSuperStructSchema(schema)) {
    return validateSuperstructSchema(state, schema)
  } else {
    throw new Error('Form validation failed: Unsupported form schema')
  }
}

export function getAtPath<T extends object>(
  data: T,
  path?: string
) {
  if (!path) return data
  const value = path
    .split('.')
    .reduce(
      (value, key) => (value as any)?.[key],
      data as any
    )

  return value
}

export function setAtPath<T extends object>(
  data: T,
  path: string,
  value: any
): T {
  if (!path) return Object.assign(data, value)
  if (!data) return data

  const keys = path.split('.')
  let current = data as Record<string, any>

  // Navigate to the parent of the target property
  for (let i = 0; i < keys.length - 1; i++) {
    const key = keys[i]!
    if (current[key] === undefined || current[key] === null) {
      // If the next key is a number, initialize as array
      if (i + 1 < keys.length && !Number.isNaN(Number(keys[i + 1]))) {
        current[key] = []
      } else {
        current[key] = {}
      }
    }

    current = current[key]
  }

  // Set the final value
  const lastKey = keys[keys.length - 1]!
  current[lastKey] = value

  return data
}

import { isEqual } from 'ohash/utils'
import { withTrailingSlash, withLeadingSlash, joinURL } from 'ufo'
import type { GetItemKeys } from '../types/utils'

export function pick<Data extends object, Keys extends keyof Data>(data: Data, keys: Keys[]): Pick<Data, Keys> {
  const result = {} as Pick<Data, Keys>

  for (const key of keys) {
    result[key] = data[key]
  }

  return result
}

export function omit<Data extends object, Keys extends keyof Data>(data: Data, keys: Keys[]): Omit<Data, Keys> {
  const result = { ...data }

  for (const key of keys) {
    // eslint-disable-next-line @typescript-eslint/no-dynamic-delete
    delete result[key]
  }

  return result as Omit<Data, Keys>
}

export function get(object: Record<string, any> | undefined, path: (string | number)[] | string, defaultValue?: any): any {
  if (typeof path === 'string') {
    path = path.split('.').map((key) => {
      const numKey = Number(key)
      return Number.isNaN(numKey) ? key : numKey
    })
  }

  let result: any = object

  for (const key of path) {
    if (result === undefined || result === null) {
      return defaultValue
    }

    result = result[key]
  }

  return result !== undefined ? result : defaultValue
}

export function set(object: Record<string, any>, path: (string | number)[] | string, value: any): void {
  if (typeof path === 'string') {
    path = path.split('.').map((key) => {
      const numKey = Number(key)
      return Number.isNaN(numKey) ? key : numKey
    })
  }

  path.reduce((acc, key, i) => {
    if (acc[key] === undefined) acc[key] = {}
    if (i === path.length - 1) acc[key] = value
    return acc[key]
  }, object)
}

export function looseToNumber(val: any): any {
  const n = Number.parseFloat(val)
  return Number.isNaN(n) ? val : n
}

export function compare<T>(value?: T, currentValue?: T, comparator?: string | ((a: T, b: T) => boolean)) {
  if (value === undefined || currentValue === undefined) {
    return false
  }

  if (typeof value === 'string') {
    return value === currentValue
  }

  if (typeof comparator === 'function') {
    return comparator(value, currentValue)
  }

  if (typeof comparator === 'string') {
    return get(value!, comparator) === get(currentValue!, comparator)
  }

  return isEqual(value, currentValue)
}

export function isEmpty(value: unknown): boolean {
  if (value == null) {
    return true
  }

  if (typeof value === 'boolean' || typeof value === 'number') {
    return false
  }

  if (typeof value === 'string') {
    return value.trim().length === 0
  }

  if (Array.isArray(value)) {
    return value.length === 0
  }

  if (value instanceof Map || value instanceof Set) {
    return value.size === 0
  }

  if (value instanceof Date || value instanceof RegExp || typeof value === 'function') {
    return false
  }

  if (typeof value === 'object') {
    for (const _ in value as object) {
      if (Object.prototype.hasOwnProperty.call(value, _)) {
        return false
      }
    }
    return true
  }

  return false
}

export function getDisplayValue<T extends Array<any>, V>(
  items: T,
  value: V | undefined | null,
  options: {
    valueKey?: GetItemKeys<T>
    labelKey?: GetItemKeys<T>
    by?: string | ((a: any, b: any) => boolean)
  } = {}
): string | undefined {
  const { valueKey, labelKey, by } = options

  const foundItem = items.find((item) => {
    const itemValue = (typeof item === 'object' && item !== null && valueKey)
      ? get(item, valueKey as string)
      : item
    return compare(itemValue, value, by)
  })

  if (isEmpty(value) && foundItem) {
    return labelKey ? get(foundItem as Record<string, any>, labelKey as string) : undefined
  }

  if (isEmpty(value)) {
    return undefined
  }

  const source = foundItem ?? value

  if (source === null || source === undefined) {
    return undefined
  }

  if (typeof source === 'object') {
    return labelKey ? get(source as Record<string, any>, labelKey as string) : undefined
  }

  return String(source)
}

export function isArrayOfArray<
  A extends any[] | any[][]
>(item: A): item is A extends Array<infer T>
  ? T extends any[]
    ? T[]
    : never
  : never {
  return Array.isArray(item[0])
}

export function mergeClasses(appConfigClass?: string | string[], propClass?: string) {
  if (!appConfigClass && !propClass) {
    return ''
  }

  return [
    ...(Array.isArray(appConfigClass) ? appConfigClass : [appConfigClass]),
    propClass
  ].filter(Boolean)
}

export function getSlotChildrenText(children: any) {
  return children.map((node: any) => {
    if (!node.children || typeof node.children === 'string') return node.children || ''
    else if (Array.isArray(node.children)) return getSlotChildrenText(node.children)
    else if (node.children.default) return getSlotChildrenText(node.children.default())
  }).join('')
}

export function transformUI(ui: any, uiProp?: any) {
  return Object.entries(ui).reduce((acc, [key, value]) => {
    acc[key] = typeof value === 'function' ? value({ class: uiProp?.[key] }) : value
    return acc
  }, { ...(uiProp || {}) })
}

export function resolveBaseURL(path?: string, baseURL?: string): string | undefined {
  if (path?.startsWith('/') && !path.startsWith('//')) {
    const _base = withLeadingSlash(withTrailingSlash(baseURL || '/'))
    if (_base !== '/' && !path.startsWith(_base)) {
      return joinURL(_base, path)
    }
  }
  return path
}

import { reactivePick } from '@vueuse/core'
import { isEqual, diff } from 'ohash/utils'
import type { LinkProps } from '../../../components/kit/XLink.vue'
import { linkKeys } from './link-keys'

export { linkKeys }

export function pickLinkProps(link: LinkProps & { [key: string]: any }) {
  const keys = Object.keys(link)

  const ariaKeys = keys.filter(key => key.startsWith('aria-'))
  const dataKeys = keys.filter(key => key.startsWith('data-'))

  const propsToInclude = [
    ...linkKeys,
    ...ariaKeys,
    ...dataKeys
  ]

  return reactivePick(link, ...propsToInclude)
}

export function isPartiallyEqual(item1: any, item2: any) {
  const diffedKeys = diff(item1, item2).reduce((filtered, q) => {
    if (q.type === 'added') {
      filtered.add(q.key)
    }
    return filtered
  }, new Set<string>())

  const item1Filtered = Object.fromEntries(Object.entries(item1).filter(([key]) => !diffedKeys.has(key)))
  const item2Filtered = Object.fromEntries(Object.entries(item2).filter(([key]) => !diffedKeys.has(key)))

  return isEqual(item1Filtered, item2Filtered)
}

import type { Ref, MaybeRef } from 'vue'
import type { Locale, Direction } from '../types/locale'
import { computed, isRef, ref, unref } from 'vue'
import { get } from './index'

export type TranslatorOption = Record<string, string | number>
export type Translator = (path: string, option?: TranslatorOption) => string
export type LocaleContext<M> = {
  locale: Ref<Locale<M>>
  lang: Ref<string>
  dir: Ref<Direction>
  code: Ref<string>
  t: Translator
}

export function buildTranslator<M>(locale: MaybeRef<Locale<M>>): Translator {
  return (path, option) => translate(path, option, unref(locale))
}

export function translate<M>(path: string, option: undefined | TranslatorOption, locale: Locale<M>): string {
  const prop: string = get(locale, `messages.${path}`, path)

  return prop.replace(
    /\{(\w+)\}/g,
    (_, key) => `${option?.[key] ?? `{${key}}`}`
  )
}

export function buildLocaleContext<M>(locale: MaybeRef<Locale<M>>): LocaleContext<M> {
  const lang = computed(() => unref(locale).name)
  const code = computed(() => unref(locale).code)
  const dir = computed(() => unref(locale).dir)
  const localeRef = isRef(locale) ? locale : ref(locale) as Ref<Locale<M>>

  return {
    lang,
    code,
    dir,
    locale: localeRef,
    t: buildTranslator(locale)
  }
}

import type { PointerDownOutsideEvent } from 'reka-ui'

export interface PointerDownOutsideOptions {
  /**
   * Whether the overlay is in scrollable mode.
   * When true, prevents closing when clicking on the scrollbar.
   */
  scrollable?: boolean
}

/**
 * Handles `pointerDownOutside` events to prevent overlays from closing in specific scenarios:
 * 1. When the target element is no longer in the DOM (e.g., a toast was dismissed between pointerdown and click on touch devices)
 * 2. When clicking on a scrollbar (only in scrollable mode)
 *
 * Note: Reka UI already handles dismissable layer checks internally via `isLayerExist`,
 * so we don't need to check for `[data-dismissable-layer]` here.
 *
 * @see https://reka-ui.com/docs/components/dialog#disable-close-on-interaction-outside
 */
export function pointerDownOutside(e: PointerDownOutsideEvent, options: PointerDownOutsideOptions = {}) {
  const originalEvent = e.detail.originalEvent
  const target = originalEvent.target as HTMLElement

  // Fix for touch devices: on touch, Reka UI defers the event dispatch to the click event.
  // If the target element was removed from DOM between pointerdown and click (e.g., toast dismissed),
  // we should prevent the overlay from closing.
  // Using `isConnected` instead of `document.body.contains()` to correctly handle Shadow DOM elements.
  if (!target?.isConnected) {
    e.preventDefault()
    return
  }

  // Scrollable mode: prevent closing when clicking on scrollbar
  // FIXME: This is a workaround to prevent the overlay from closing when clicking on the scrollbar https://reka-ui.com/docs/components/dialog#scrollable-overlay but it's not working on Mac OS.
  if (options.scrollable) {
    if (originalEvent.offsetX > target.clientWidth || originalEvent.offsetY > target.clientHeight) {
      e.preventDefault()
    }
  }
}

// Prefetch helpers for the Nuxt `Link` component. Kept out of `utils/link.ts`
// so the Vue builds, which share `LinkBase` but never render `NuxtLink`, do not
// load them.

type IdleCallbackHandle = ReturnType<typeof setTimeout> | number

// Mirrors Nuxt's `requestIdleCallback` compat: falls back to a short timeout
// when the browser (or happy-dom in tests) does not implement it.
export function requestIdleCallback(callback: () => void): IdleCallbackHandle | undefined {
  if (typeof window === 'undefined') {
    return
  }

  if (typeof window.requestIdleCallback === 'function') {
    return window.requestIdleCallback(callback)
  }

  return setTimeout(callback, 1)
}

export function cancelIdleCallback(handle: IdleCallbackHandle | undefined) {
  if (typeof window === 'undefined' || handle === undefined) {
    return
  }

  if (typeof window.cancelIdleCallback === 'function') {
    window.cancelIdleCallback(handle as number)
    return
  }

  clearTimeout(handle as ReturnType<typeof setTimeout>)
}

let observer: IntersectionObserver | null = null
const callbacks = new Map<Element, () => void>()

// One `IntersectionObserver` shared by every link, like NuxtLink's own observer:
// creating one per link is wasteful for navigations with hundreds of entries.
export function observeIntersection(element: Element, callback: () => void): () => void {
  if (typeof IntersectionObserver === 'undefined') {
    return () => {}
  }

  observer ||= new IntersectionObserver((entries) => {
    for (const entry of entries) {
      const callback = callbacks.get(entry.target)
      if ((entry.isIntersecting || entry.intersectionRatio > 0) && callback) {
        callback()
      }
    }
  })

  callbacks.set(element, callback)
  observer.observe(element)

  return () => {
    callbacks.delete(element)
    observer?.unobserve(element)

    if (callbacks.size === 0) {
      observer?.disconnect()
      observer = null
    }
  }
}

/** fuse.js 未随包安装，本地宽松类型替代（仅类型层） */
type FuseResult<T> = { matches?: readonly FuseResultMatch[] }
type FuseResultMatch = { key?: string; value: string; indices: ReadonlyArray<readonly [number, number]> }
import type { GetItemKeys } from '../types/utils'

const htmlEscapes: Record<string, string> = {
  '&': '&amp;',
  '<': '&lt;',
  '>': '&gt;',
  '"': '&quot;',
  '\'': '&#39;'
}

function escapeHTML(str: string): string {
  return str.replace(/[&<>"']/g, char => htmlEscapes[char]!)
}

function truncateHTMLFromStart(html: string, maxLength: number) {
  let truncated = ''
  let totalLength = 0
  let insideTag = false

  // Iterate through the HTML string in reverse order, one code point at a time.
  // Indexing by UTF-16 code unit would slice an astral character (emoji, most
  // CJK extension blocks) in half when the truncation boundary lands between
  // its surrogates, emitting an unpaired surrogate that renders as `�`.
  // `<` and `>` are always single code units, so tag tracking is unaffected.
  const chars = Array.from(html)

  for (let i = chars.length - 1; i >= 0; i--) {
    const char = chars[i]!

    if (char === '>') {
      insideTag = true
    } else if (char === '<') {
      insideTag = false
      truncated = char + truncated
      continue
    }

    if (!insideTag) {
      totalLength++
    }

    if (totalLength <= maxLength) {
      truncated = char + truncated
    } else {
      // If we've reached the max length, we break out of the loop
      // to prevent further processing of the string
      truncated = '...' + truncated
      break
    }
  }

  return truncated
}

// Escape an FTS snippet to safe HTML while preserving the `<mark>` highlight tags.
// The tag is intentionally hardcoded — exposing it as a parameter would let a
// caller smuggle through arbitrary tags (e.g. `<script>`) since `v-html` is
// used to render the result downstream.
export function sanitizeSnippet(snippet: string): string {
  const tagOpen = '\0markO\0'
  const tagClose = '\0markC\0'

  return escapeHTML(
    snippet
      .replaceAll('<mark>', tagOpen)
      .replaceAll('</mark>', tagClose)
  )
    .replaceAll(tagOpen, '<mark>')
    .replaceAll(tagClose, '</mark>')
}

export function highlight<T>(item: T & { matches?: FuseResult<T>['matches'] }, searchTerm: string, forceKey?: GetItemKeys<T>, omitKeys?: GetItemKeys<T>[], useTokenSearch?: boolean) {
  const tokens = useTokenSearch ? (searchTerm.match(/[\p{L}\p{M}\p{N}_]+/gu) || []) : []
  const minTokenLength = tokens.length > 0 ? Math.min(...tokens.map(t => t.length)) : searchTerm.length

  function generateHighlightedText(value: FuseResultMatch['value'], indices: FuseResultMatch['indices'] = []) {
    value = value || ''
    let content = ''
    let nextUnhighlightedRegionStartingIndex = 0

    indices.forEach((region) => {
      // skip if region is a single character
      if (region.length === 2 && region[0] === region[1]) {
        return
      }

      const lastIndiceNextIndex = region[1] + 1
      const isMatched = (lastIndiceNextIndex - region[0]) >= minTokenLength

      content += [
        escapeHTML(value.substring(nextUnhighlightedRegionStartingIndex, region[0])),
        isMatched && `<mark>`,
        escapeHTML(value.substring(region[0], lastIndiceNextIndex)),
        isMatched && '</mark>'
      ].filter(Boolean).join('')

      nextUnhighlightedRegionStartingIndex = lastIndiceNextIndex
    })

    content += escapeHTML(value.substring(nextUnhighlightedRegionStartingIndex))

    const markIndex = content.indexOf('<mark>')
    if (markIndex !== -1) {
      // Measure the budget in code points too, so it stays in the same units as
      // the counter inside `truncateHTMLFromStart`. Identical to `.length` for
      // BMP-only content.
      content = truncateHTMLFromStart(content, Array.from(content.slice(markIndex)).length)
    }

    return content
  }

  if (!item.matches?.length) {
    return
  }

  for (const match of item.matches) {
    if (forceKey && match.key !== forceKey) {
      continue
    }
    if (omitKeys?.includes(match.key as GetItemKeys<T>)) {
      continue
    }

    return generateHighlightedText(match.value, match.indices)
  }
}

import { createTV, cnMerge } from 'tailwind-variants'
import type { ClassValue, TVVariants, TVCompoundVariants, TVDefaultVariants, TVReturnType, defaultConfig } from 'tailwind-variants'
import type { AppConfig } from '@/lib/nuxt/types/app-config'
import type { SlotClassReplacer } from '../types/tv'
import appConfig from '@/lib/nuxt/app-config'

// Internal `tailwind-variants` helpers that are not re-exported.
type TVSlots = Record<string, ClassValue> | undefined

/**
 * Widen the slot functions of a `tailwind-variants` return type so `class` /
 * `className` also accept the `(defaults) => classes` replacer — `:ui` and the
 * `class` prop flow straight into them. The concrete slot keys (and the
 * extend-readable `slots` / `variants` / … properties) are preserved, so
 * components keep type-checking under `noUncheckedIndexedAccess`.
 */
type WideSlotFn = (slotProps?: Record<string, any>) => string
type Widen<R> = R extends (props?: infer P) => infer Slots
  ? { (props?: P): Slots extends string ? string : { [K in keyof Slots]: WideSlotFn } } & Omit<R, never>
  : R

/**
 * Mirrors `tailwind-variants`' `TV` call signature (so config inference is
 * unchanged) but returns the {@link Widen}-ed result. Component prop types are
 * derived from `typeof theme` via `ComponentConfig`, not from this type, so the
 * widening only affects the internal `ui.slot(...)` calls.
 */
type WideTV = {
  <
    V extends TVVariants<S, B, EV>,
    CV extends TVCompoundVariants<V, S, B, EV, ES>,
    DV extends TVDefaultVariants<V, S, EV, ES>,
    B extends ClassValue = undefined,
    S extends TVSlots = undefined,
    // @ts-expect-error mirror of tailwind-variants' own circular default
    E extends TVReturnType = TVReturnType<V, S, B, EV extends undefined ? {} : EV, ES extends undefined ? {} : ES>,
    EV extends TVVariants<ES, B, E['variants'], ES> = E['variants'],
    ES extends TVSlots = E['slots'] extends TVSlots ? E['slots'] : undefined
  >(
    options: {
      extend?: E
      base?: B
      slots?: S
      variants?: V
      compoundVariants?: CV
      compoundSlots?: any
      defaultVariants?: DV
    },
    config?: typeof defaultConfig
  ): Widen<TVReturnType<V, S, B, EV, ES, E>>
}

const appConfigTv = appConfig as AppConfig & { ui: { tv: typeof defaultConfig } }

const config = appConfigTv.ui?.tv

const baseTv = /* @__PURE__ */ createTV(config)

/**
 * Find a **call-time** class replacer — a function `(defaults) => classes` that
 * replaces a slot's resolved classes instead of merging onto them. It may sit
 * directly in a slot's `class` value (the `transformUI` scalar path) or inside the array a
 * component forwards (e.g. `[props.ui?.base, props.class]`). Arrays are scanned
 * deeply and the **last** replacer wins, mirroring `twMerge`'s last-in-wins
 * semantics so e.g. `props.class` overrides `props.ui?.base`.
 */
function findReplacer(value: unknown): SlotClassReplacer | undefined {
  if (typeof value === 'function') {
    return value as SlotClassReplacer
  }
  if (Array.isArray(value)) {
    for (let i = value.length - 1; i >= 0; i--) {
      const replacer = findReplacer(value[i])
      if (replacer) {
        return replacer
      }
    }
  }
  return undefined
}

/**
 * Keep the plain (non-function) classes passed alongside a replacer so they
 * still apply on top of the replacement. Nested arrays are flattened so plain
 * classes are never dropped.
 */
function plainClasses(value: unknown): ClassValue[] {
  if (Array.isArray(value)) {
    return value.flatMap(item => plainClasses(item))
  }
  if (typeof value === 'function') {
    return []
  }
  return [value as ClassValue]
}

/**
 * Apply a call-time replacer: drop the resolved class chain (base + variants +
 * compound variants) and return only the replacement, plus any plain classes
 * passed alongside it. `resolveDefaults` computes that chain without any user
 * class so the replacer can reuse part of it.
 */
function applyReplacer(replacer: SlotClassReplacer, slotProps: Record<string, any>, resolveDefaults: () => string): string {
  return cnMerge(replacer(resolveDefaults()), ...plainClasses(slotProps.class), ...plainClasses(slotProps.className))(config) ?? ''
}

/**
 * A slot invocation is memoizable only when its output is fully determined by a
 * serializable key: primitives and arrays of primitives. Objects (clsx-style
 * class maps) and functions (replacers) bail to the uncached path.
 */
function isMemoizable(value: unknown, depth = 0): boolean {
  if (value === undefined || value === null) {
    return true
  }
  const type = typeof value
  if (type === 'string' || type === 'boolean') {
    return true
  }
  // `JSON.stringify` turns NaN/Infinity into `null`, colliding with real `null`
  // keys that tv resolves differently (default variant vs `key || "false"` lookup).
  if (type === 'number') {
    return Number.isFinite(value)
  }
  if (Array.isArray(value)) {
    // Stop a few levels down rather than recurse without bound: a cyclic array
    // reaching a variant would blow the stack, where tv itself resolves it. The
    // arrays components pass (`[props.ui?.td, ...]`) are one or two deep.
    if (depth >= 4) {
      return false
    }
    for (const item of value) {
      if (!isMemoizable(item, depth + 1)) {
        return false
      }
    }
    return true
  }
  return false
}

function memoKey(slotProps: Record<string, any>): string | undefined {
  // Only plain objects: an exotic prototype could carry inherited enumerable
  // props that tv would read but `JSON.stringify` would drop from the key,
  // making two different inputs share one cache entry.
  const proto = Object.getPrototypeOf(slotProps)
  if (proto !== Object.prototype && proto !== null) {
    return undefined
  }

  // `Object.keys` matches exactly what `JSON.stringify` serializes (own
  // enumerable keys), so everything the key omits is also never inspected here.
  for (const key of Object.keys(slotProps)) {
    if (!isMemoizable(slotProps[key])) {
      return undefined
    }
  }
  // `JSON.stringify` drops `undefined`-valued keys, matching tv's semantics
  // (an undefined variant is the same as an absent one).
  return JSON.stringify(slotProps)
}

/**
 * Wrap the slot functions returned by `tv()` so a replacer passed at call time
 * (`:ui` / `class`, which includes what `<UTheme>` injects) drops the slot's
 * resolved class chain and returns only its replacement. Without a replacer the
 * original slot function runs untouched, so the common merge path is unaffected.
 *
 * Repeated invocations with identical simple args (re-renders, table cells) are
 * memoized per slot: variant resolution + twMerge only run once per distinct
 * input. The cache lives on the invocation result, so a factory rebuild (e.g.
 * `app.config.ui` change) or variant-prop recompute starts fresh.
 */
function wrapSlots(slots: Record<string, any>) {
  // `undefined` is a real slot result: `tv` returns it (not `''`) for a slot
  // whose chain resolves to no classes, so it can't double as a miss sentinel.
  const memo = new Map<string, Map<string, string | undefined>>()

  return new Proxy(slots, {
    get(target, key: string) {
      const slot = target[key]
      if (typeof slot !== 'function') {
        return slot
      }

      return (slotProps: Record<string, any> = {}) => {
        const replacer = findReplacer(slotProps.class) ?? findReplacer(slotProps.className)
        if (!replacer) {
          const cacheKey = memoKey(slotProps)
          if (cacheKey === undefined) {
            return slot(slotProps)
          }

          let cache = memo.get(key)
          if (!cache) {
            cache = new Map()
            memo.set(key, cache)
          }

          let result = cache.get(cacheKey)
          // The extra `has` only runs for the rare slot that resolves to no
          // classes, so the hot path stays a single lookup.
          if (result === undefined && !cache.has(cacheKey)) {
            if (cache.size >= 500) {
              // Pathological dynamic inputs (e.g. per-row generated classes):
              // reset rather than grow unbounded.
              cache.clear()
            }
            result = slot(slotProps) as string
            cache.set(cacheKey, result)
          }
          return result
        }
        return applyReplacer(replacer, slotProps, () => slot({ ...slotProps, class: undefined, className: undefined }))
      }
    }
  })
}

/**
 * Flatten a raw theme class value (string, array, nested array with falsy holes)
 * into the string a replacer receives as its `defaults` argument.
 */
function defaultClasses(value: unknown): string {
  return cnMerge(value as ClassValue)(config) ?? ''
}

/**
 * Resolve construction-time replacers authored in `app.config.ui.<component>`
 * (under `slots` or the top-level `base`) so `createTV` only ever receives valid
 * class strings. The replacer takes the place of the slot's **own** classes from
 * the extended theme, which means `variants` and `compoundVariants` still merge
 * on top of the result — the same as when a plain string is used.
 *
 * Blanking the entry on the `extend` side is what makes it a replacement: `tv`
 * only ever concatenates the extended theme into the component's own classes, it
 * has no way to remove them. Call-time replacers (`:ui` / `class`) run after
 * variant resolution instead and are handled in {@link wrapSlots}. The incoming
 * config is never mutated.
 */
function resolveReplacers(componentConfig: any): any {
  if (!componentConfig || typeof componentConfig !== 'object') {
    return componentConfig
  }

  const slots = componentConfig.slots
  const replacers = slots && typeof slots === 'object'
    ? Object.entries(slots).filter((entry): entry is [string, SlotClassReplacer] => typeof entry[1] === 'function')
    : []
  const baseReplacer = typeof componentConfig.base === 'function' ? componentConfig.base as SlotClassReplacer : undefined

  if (!replacers.length && !baseReplacer) {
    return componentConfig
  }

  const extend = componentConfig.extend
  const resolved = { ...componentConfig }
  // Only rebuilt when there is something to blank, so an `extend`-less config
  // (or one whose replaced slots aren't in the extended theme) is left alone.
  let extendSlots: Record<string, any> | undefined
  let blankExtendBase = false

  if (baseReplacer) {
    // A slotted component keeps its base under `slots.base`, a slotless one under
    // the top-level `base`, so read whichever the extended theme actually has.
    resolved.base = baseReplacer(defaultClasses(extend?.slots?.base ?? extend?.base))
    if (extend?.slots?.base) {
      extendSlots ??= { ...extend.slots } as Record<string, any>
      extendSlots.base = ''
    }
    if (extend?.base) {
      blankExtendBase = true
    }
  }

  if (replacers.length) {
    const cleaned = { ...slots }
    for (const [slot, replacer] of replacers) {
      cleaned[slot] = replacer(defaultClasses(extend?.slots?.[slot]))
      if (extend?.slots?.[slot]) {
        extendSlots ??= { ...extend.slots } as Record<string, any>
        extendSlots[slot] = ''
      }
    }
    resolved.slots = cleaned
  }

  if (extendSlots || blankExtendBase) {
    const cleanedExtend = { ...extend }
    if (extendSlots) {
      cleanedExtend.slots = extendSlots
    }
    if (blankExtendBase) {
      cleanedExtend.base = ''
    }
    resolved.extend = cleanedExtend
  }

  return resolved
}

/**
 * Wraps `tailwind-variants`' `tv` so slot classes can be **replaced** (not just
 * merged) through a function form — `(defaults) => classes` — in `:ui`, the
 * `class` prop and `app.config.ui`. The wrapper is transparent for every other
 * usage: it preserves the `TVReturnType` (so `extend: theme` keeps working
 * via property reads) and only intercepts the slot functions on invocation.
 */
export const tv = ((componentConfig?: any) => {
  const component = baseTv(resolveReplacers(componentConfig))

  return new Proxy(component, {
    apply(target, thisArg, args) {
      const result = Reflect.apply(target, thisArg, args)
      if (result && typeof result === 'object') {
        return wrapSlots(result)
      }

      // Slotless components (only a `base`, no `slots`) return a string. Honor a
      // replacer passed through `class` / `className`, otherwise return the
      // merged string untouched.
      if (typeof result === 'string') {
        const slotProps = args[0] ?? {}
        const replacer = findReplacer(slotProps.class) ?? findReplacer(slotProps.className)
        if (replacer) {
          return applyReplacer(replacer, slotProps, () => Reflect.apply(target, thisArg, [{ ...slotProps, class: undefined, className: undefined }]))
        }
      }

      return result
    }
  })
}) as unknown as WideTV

import { get } from './index'

function itemHasDescription(item: any, descriptionKey: string): boolean {
  if (typeof item !== 'object' || item === null) {
    return false
  }
  const value = get(item, descriptionKey)
  return value !== undefined && value !== null && value !== ''
}

function getSize(size: 'xs' | 'sm' | 'md' | 'lg' | 'xl' | (string & {}), hasDescription: boolean): number {
  const sizes = hasDescription
    ? {
        xs: 44,
        sm: 48,
        md: 52,
        lg: 56,
        xl: 60
      }
    : {
        xs: 24,
        sm: 28,
        md: 32,
        lg: 36,
        xl: 40
      }

  return sizes[size as keyof typeof sizes] ?? sizes.md
}

/**
 * Get estimate size for virtualizers that checks each item individually
 */
export function getEstimateSize(items: any[], size: 'xs' | 'sm' | 'md' | 'lg' | 'xl' | (string & {}), descriptionKey?: string, hasDescriptionSlot?: boolean): (index: number) => number {
  const sizeWithDescription = getSize(size, true)
  const sizeWithoutDescription = getSize(size, false)

  // If description slot is used, all items get the larger size
  if (hasDescriptionSlot) {
    return () => sizeWithDescription
  }

  // If no descriptionKey, all items get the smaller size
  if (!descriptionKey) {
    return () => sizeWithoutDescription
  }

  return (index: number) => {
    return itemHasDescription(items[index], descriptionKey) ? sizeWithDescription : sizeWithoutDescription
  }
}
